-- 修复已在旧版批次 SQL 中插入、但尚未关联 current_revision_id 的 14 条候选。
WITH batch(submission_id, revision_id) AS (
  VALUES
    ('51000000-0000-4000-8100-000000000001'::uuid, '61000000-0000-4000-8100-000000000001'::uuid),
    ('51000000-0000-4000-8100-000000000002'::uuid, '61000000-0000-4000-8100-000000000002'::uuid),
    ('51000000-0000-4000-8100-000000000003'::uuid, '61000000-0000-4000-8100-000000000003'::uuid),
    ('51000000-0000-4000-8100-000000000004'::uuid, '61000000-0000-4000-8100-000000000004'::uuid),
    ('51000000-0000-4000-8100-000000000005'::uuid, '61000000-0000-4000-8100-000000000005'::uuid),
    ('51000000-0000-4000-8100-000000000006'::uuid, '61000000-0000-4000-8100-000000000006'::uuid),
    ('51000000-0000-4000-8100-000000000007'::uuid, '61000000-0000-4000-8100-000000000007'::uuid),
    ('51000000-0000-4000-8100-000000000008'::uuid, '61000000-0000-4000-8100-000000000008'::uuid),
    ('51000000-0000-4000-8100-000000000009'::uuid, '61000000-0000-4000-8100-000000000009'::uuid),
    ('51000000-0000-4000-8100-000000000010'::uuid, '61000000-0000-4000-8100-000000000010'::uuid),
    ('51000000-0000-4000-8100-000000000011'::uuid, '61000000-0000-4000-8100-000000000011'::uuid),
    ('51000000-0000-4000-8100-000000000012'::uuid, '61000000-0000-4000-8100-000000000012'::uuid),
    ('51000000-0000-4000-8100-000000000013'::uuid, '61000000-0000-4000-8100-000000000013'::uuid),
    ('51000000-0000-4000-8100-000000000014'::uuid, '61000000-0000-4000-8100-000000000014'::uuid)
)
UPDATE submissions
SET current_revision_id = batch.revision_id, updated_at = now()
FROM batch
WHERE submissions.id = batch.submission_id
  AND submissions.current_revision_id IS NULL
  AND EXISTS (SELECT 1 FROM submission_revisions WHERE id = batch.revision_id);
